import{_ as s,o as t,c as a,a0 as o}from"./chunks/framework.ChlVJx0I.js";const f=JSON.parse('{"title":"Tool usage counts are derived from a session scan with a per-file stat-keyed cache","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0014-tool-usage-counts-cached-session-scan.md","filePath":"adr/0014-tool-usage-counts-cached-session-scan.md","lastUpdated":1789568117000}'),n={name:"adr/0014-tool-usage-counts-cached-session-scan.md"};function i(c,e,r,l,d,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="tool-usage-counts-are-derived-from-a-session-scan-with-a-per-file-stat-keyed-cache" tabindex="-1">Tool usage counts are derived from a session scan with a per-file stat-keyed cache <a class="header-anchor" href="#tool-usage-counts-are-derived-from-a-session-scan-with-a-per-file-stat-keyed-cache" aria-label="Permalink to &quot;Tool usage counts are derived from a session scan with a per-file stat-keyed cache&quot;">​</a></h1><p>/ctx shows how often each tool was called, so the token cost of a tool can be weighed against its use. The session JSONL files already record every tool call (a <code>toolCall</code> item inside an assistant message), so the counts are derived from the session files: the same source of truth as the Usage scan. A forked session copies its ancestor&#39;s lines byte-identical, so a line counts once per distinct line (ADR 0009).</p><p>Unlike the Usage report (ADR 0008: no stored aggregate, every report pays a full scan), the tool usage scan keeps a per-file cache keyed on mtime and size. /ctx opens interactively: the dialog must render while the scan runs, and a window switch (30d, 90d, all) must not re-scan. The cache stores, per file, the all-time counts, the <code>(ts, tool)</code> events inside the newest 90 days, and the hashes of the lines that carried a tool call (the dedupe keys, surviving across scan passes so a fork never double-counts after a restart). The cache carries a format version; a mismatch reads as an empty cache, so a scan change that adds count keys invalidates every existing cache at once.</p><p>The cache is a pure function of the session files. Every entry is invalid the moment its file&#39;s mtime or size changes, a file that leaves the tree drops its entry, and deleting the cache file costs exactly one re-scan. It never decides a count on its own, so it is a cache in the strict sense, not a second source of truth. It lives at <code>~/.pi/agent/tool-usage-cache.json</code>, next to (never inside) the sessions tree, and <code>PI_TOOL_USAGE_CACHE</code> points it elsewhere.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>No cache, a full scan on every open (ADR 0008&#39;s rule).</strong> Correct and simple, but every first open stalls the dialog for the scan&#39;s duration (about 2.5 seconds at 900 MB of sessions) and every window switch would re-scan. The dialog renders a counting state while the scan runs, which masks the first scan; the cache then makes all later opens and switches near instant.</li><li><strong>A live append ledger written by the extension while sessions run.</strong> Instant reads, but a second source of truth that misses calls made in sessions the extension did not watch (other machines, the extension disabled) and drifts from the session files. The codegraph Usage log is different: it records facts the session files do not carry (outcome, duration, result size) for the index that owns it.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The first /ctx after a cache miss pays a full scan (about 2.5 seconds at 900 MB) in the background; the dialog shows the counting state. Every later open is near instant, and switching windows is a filter on cached events.</li><li>A count is complete for the sessions present on this machine. The scan sees only the local sessions tree, same as the Usage scan.</li><li>If pi ever stops writing <code>toolCall</code> items to the session files, the counts silently go to zero; the e2e on a fixture session tree guards the shape.</li></ul>',8)])])}const p=s(n,[["render",i]]);export{f as __pageData,p as default};
